<?php declare(strict_types=1); require_once dirname(__DIR__,2).'/lib/tool-page.php'; $tool=['title'=>'Free Unit Prefix Converter','description'=>'Convert values between kilo, mega, giga, milli, micro and base units.','url'=>'https://smarttoolz.in/tools/unit-prefix-converter/']; smarttoolz_tool_page_start($tool); ?><main class="tool-page"><section class="tool-intro"><h1>Unit Prefix Converter</h1><p>Convert SI-prefixed values instantly.</p></section><section class="tool-workspace"><div class="tool-panel"><label>Value<input id="v" type="number" value="1"></label><label>From<select id="a"><option>base</option><option>kilo</option><option>mega</option><option>giga</option><option>milli</option><option>micro</option></select></label><label>To<select id="b"><option>kilo</option><option>base</option><option>mega</option><option>giga</option><option>milli</option><option>micro</option></select></label><button id="go" class="tool-btn">Convert</button><p id="o"></p></div></section></main><script>let z={base:1,kilo:1e3,mega:1e6,giga:1e9,milli:1e-3,micro:1e-6};go.onclick=()=>o.textContent=(+v.value*z[a.value]/z[b.value]).toPrecision(12)</script><?php smarttoolz_tool_page_end(); ?>